	g.Go(func() error {
		logger.Info("starting HTTP auth service", logKeyPort, httpPort)
		err := httpSrv.ListenAndServe()
		if err != nil && !errors.Is(err, http.ErrServerClosed) {
			return err
		}
		return nil
